def solution(text, max_words, overlap):
    # Brute force: keep the chunk as a string and re-count its words with split()
    # every time we need its length, and carry overlap by re-splitting the string.
    words = text.split()
    sentences, start = [], 0
    for i in range(len(words)):
        if words[i][-1] in '.?!':
            sentences.append(' '.join(words[start:i + 1]))
            start = i + 1
    if start < len(words):
        sentences.append(' '.join(words[start:]))

    def count(s):
        return len(s.split())

    def tail(s):
        if overlap == 0:
            return ''
        return ' '.join(s.split()[-overlap:])

    chunks, chunk, has_new = [], '', False
    for sent in sentences:
        joined = (chunk + ' ' + sent).strip()
        if count(joined) <= max_words:
            chunk, has_new = joined, True
            continue
        if has_new:
            chunks.append(chunk)
            chunk, has_new = tail(chunk), False
            joined = (chunk + ' ' + sent).strip()
            if count(joined) <= max_words:
                chunk, has_new = joined, True
                continue
        for w in sent.split():
            if count(chunk) == max_words:
                chunks.append(chunk)
                chunk = tail(chunk)
            chunk = (chunk + ' ' + w).strip()
            has_new = True
    if has_new:
        chunks.append(chunk)
    return chunks
